// 顶点小说 · 原生
fn yxStatus(st, lc, ut) {
  let s = trim(str(st))
  if (test(s, '完本|完结')) { return '已完结' }
  if (test(str(lc), '大结局|全书完|终章|完结')) { return '已完结' }
  let y = int(substring(trim(str(ut)), 0, 4), 0)
  let cy = int(substring(formatDate(now(), 'yyyy'), 0, 4), 0)
  if (y > 2000 && cy - y >= 2) { return '已完结' }
  if (test(s, '连载')) { return '连载中' }
  return s
}
fn yxCover(h) {
  let m = match(str(h), '([0-9]+)_([0-9]+)', 2)
  if (m == null) { return '' }
  let id = str(m)
  return '/files/article/image/' + str(floor(int(id, 0) / 1000)) + '/' + id + '/' + id + 's.jpg'
}
// 站点把换行存成两个字符（反斜杠+n），用 split/join 全局还原为真换行
fn yxFixLines(t) {
  let bs = fromCharCode(92)
  let nl = fromCharCode(10)
  t = join(split(t, bs + 'r' + bs + 'n'), nl)
  t = join(split(t, bs + 'n'), nl)
  t = join(split(t, bs + 'r'), '')
  t = join(split(t, fromCharCode(13)), '')
  return t
}
fn yxClean(h) { return trim(yxFixLines(htmlDecode(replace(str(h), '<[^>]*>', '', 'g')))) }
// 正文：先删 center_tip 广告块（用索引定位，避免正则转义），再解码与还原换行
fn yxBody(h) {
  let s = str(h)
  let a = indexOf(s, '<div id="center_tip">')
  if (a >= 0) {
    let b = indexOf(s, '</div>', a)
    if (b > a) { s = substring(s, 0, a) + substring(s, b + 6, len(s)) }
  }
  return yxFixLines(htmlDecode(s))
}
